B.b44={"remo-mano":0,frontales:1,bulgara:2,zancadas:3,"step-up":4,"plancha-lateral":5,"bird-dog":6,"dead-bug":7,bicicleta:8,"toques-talon":9}
B.b2K=new A.S(B.b44,["por brazo","por brazo","por pierna","por pierna","por pierna","por lado","por lado","por lado","por lado","por lado"],t.w)
B.b4b={"\xbd":0,"\xbc":1,"\xbe":2,"\u2153":3,"\u2154":4}
